"</th>\r\n    </tr>\r\n  </thead>\r\n  <tbody>\r\n    <tr>\r\n      <td>TRUE</td>\r\n      <td>FALSE</td>\r\n      <td>TRUE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>TRUE</td>\r\n      <td>FALSE</td>\r\n    </tr>\r\n    <tr>\r\n      <td>FALSE</td>\r\n      <td>TRUE</td>\r\n      <td>FALSE</td>\r\n      <td>TRUE</td>\r\n      <td>TRUE</td>\r\n      <td>FALSE</td>\r\n      <td>TRUE</td>\r\n    </tr>\r\n    <tr>\r\n      <td>1</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n    </tr>\r\n    <tr>\r\n      <td>0</td>\r\n      <td>TRUE</td>\r\n      <td>FALSE</td>\r\n      <td>TRUE</td>\r\n      <td>FALSE</td>\r\n      <td>TRUE</td>\r\n      <td>TRUE</td>\r\n    </tr>\r\n    <tr>\r\n      <td>-1</td>\r\n      <td>FALSE</td>\r\n      <td>TRUE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n    </tr>\r\n    <tr>\r\n      <td>\"1\"</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n    </tr>\r\n    <tr>\r\n      <td>\"0\"</td>\r\n      <td>TRUE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n    </tr>\r\n    <tr>\r\n      <td>\"-1\"</td>\r\n      <td>FALSE</td>\r\n      <td>TRUE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n    </tr>\r\n    <tr>\r\n      <td>NULL</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>TRUE</td>\r\n      <td>TRUE</td>\r\n      <td>FALSE</td>\r\n      <td>TRUE</td>\r\n    </tr>\r\n    <tr>\r\n      <td>array()</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n      <td>TRUE</td>\r\n      <td>TRUE</td>\r\n      <td>FALSE</td>\r\n      <td>FALSE</td>\r\n    </tr>\r\n    <tr>\r\n      <td>\"php\"</td>\r\n      <td>